-- GENERATED FILE — do not edit by hand.
-- Regenerate: python3 scripts/aml/build-aml-v11-reference-draft.py
-- Creates/refreshes the AML-CFT-RBA v1.1 DRAFT methodology version from the
-- MIPL reference catalogue, entirely through governed operations.
\set ON_ERROR_STOP on
BEGIN;

DO $guard$ BEGIN
  IF public.is_production_environment() THEN
    RAISE EXCEPTION 'refused: reference methodology draft creation is not a production operation';
  END IF;
END $guard$;

CREATE TEMP TABLE tmp_dim_questions(dimension_code text PRIMARY KEY, questions jsonb) ON COMMIT DROP;
INSERT INTO tmp_dim_questions VALUES ($lit$CUSTOMER_RISK$lit$, $json$[{"question_code": "IR-CUS-01", "prompt": "Higher-risk customer classes represent a material share of the customer base.", "guidance": "Assess against the classes the entity itself, or supervisory guidance, treats as higher ML/TF risk. Materiality is judged on share and on absolute count for a small entity; the share thresholds are configuration parameters ([MAT_HIGH_RISK_CUSTOMER_SHARE], [MAT_HIGH_RISK_VALUE_SHARE]), not fixed question wording. Record the figures used. Absence of a customer risk classification is a CONTROL weakness recorded under CDD_KYC / ENTERPRISE_RISK_ASSESSMENT, not a NO here.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-CUS-02", "prompt": "Legal persons, trusts, nominee or otherwise complex customer structures are material to the business.", "guidance": "Consider companies, partnerships, foundations, trusts, nominee shareholdings and multi-layer or multi-jurisdiction structures. Judge on share of relationships and share of value. Bearer-instrument or nominee-director features raise the response.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-CUS-03", "prompt": "Non-resident or cross-border customers are material to the business.", "guidance": "Base on residence/domicile of customers and beneficial owners, not the currency of transactions. Distinguish incidental non-residents from a deliberate non-resident line of business.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-CUS-04", "prompt": "Politically exposed persons and their close associates are material to the customer base.", "guidance": "Include domestic and foreign PEPs, family members and close associates, and PEPs who are beneficial owners rather than account holders. For a small entity a single significant PEP relationship may be material; state the reasoning.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$GEOGRAPHIC_RISK$lit$, $json$[{"question_code": "IR-GEO-01", "prompt": "The entity has material exposure to higher-risk or monitored jurisdictions.", "guidance": "Use the jurisdiction lists applicable in the deployment ([LOCAL_HIGH_RISK_LIST_REF]) together with FATF public identification statements. Consider customer residence, beneficial-owner nationality, counterparty location and transaction corridors. Quantify share of value where possible.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-GEO-02", "prompt": "Cross-border, correspondent or remittance flows are material to the business, by volume and value.", "guidance": "Use volume, value and counterparty facts. Materiality thresholds are configuration parameters ([MAT_XBORDER_VALUE_SHARE]). Merged from v1.1 draft IR-GEO-02 and IR-TRX-03; corridor concentration context is IR-GEO-03.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "IR-GEO-03", "prompt": "Cross-border or corridor activity is concentrated in a small number of jurisdictions or corridors (contextual fact — not scored).", "guidance": "Record the largest single corridor share, the top-three share and the risk classification of those corridors. Concentration in lower-risk corridors is not adverse; concentration in higher-risk corridors amplifies IR-GEO-01 and is judged there. Share thresholds are configuration parameters ([MAT_CORRIDOR_TOP1_SHARE], [MAT_CORRIDOR_TOP3_SHARE]), not fixed wording.", "mandatory": false, "requires_observation": false, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$PRODUCTS_SERVICES_RISK$lit$, $json$[{"question_code": "IR-PRD-01", "prompt": "The entity offers products or services with anonymity, opacity or third-party value-transfer features that are material to the business.", "guidance": "Consider bearer or pooled arrangements, omnibus and client accounts, prepaid or stored-value instruments, third-party payments and payments to or from unrelated parties. Existence of mitigating controls is not considered here.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-PRD-02", "prompt": "Cash-intensive products, services or transaction activity are material to the business.", "guidance": "Judge on the share of revenue, value and transaction count that is cash or cash-equivalent, and on absolute cash value for a small entity. Materiality thresholds are configuration parameters ([MAT_CASH_VALUE_SHARE]). Merged from v1.1 draft IR-PRD-02 and IR-TRX-02.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "IR-PRD-03", "prompt": "Products permit rapid or immediate movement of value, including across borders.", "guidance": "Consider instant payments, same-day remittance, virtual-asset transfers, early surrender or redemption features and rapid pass-through capability.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-PRD-04", "prompt": "The entity offers complex, structured, or virtual-asset related products that are material to the business.", "guidance": "Include virtual assets and related services, structured or derivative products, trade finance, and multi-party arrangements. New or materially changed products in the period raise the response where launched at scale; the adequacy of the pre-launch assessment is a CONTROL matter under ENTERPRISE_RISK_ASSESSMENT.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$TRANSACTION_PROFILE_RISK$lit$, $json$[{"question_code": "IR-TRX-01", "prompt": "Transaction volume or value is material in absolute terms and relative to comparable entities.", "guidance": "Use the entity return data for the period, with peer comparison where a peer group exists. Scale alone is exposure, not a deficiency.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-TRX-04", "prompt": "Observed activity shows high velocity, pass-through behaviour, or unusual concentration of value, counterparties or corridors.", "guidance": "Consider funds in and out within short periods, balances turned over many times, single counterparties dominating volume, or activity inconsistent with the declared business model. A supervisory observation here does not by itself imply a monitoring failure; that judgement belongs to TRANSACTION_MONITORING.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$DELIVERY_CHANNEL_RISK$lit$, $json$[{"question_code": "IR-DEL-01", "prompt": "Non-face-to-face or fully remote onboarding is material to the business.", "guidance": "Report the share of relationships onboarded remotely. The quality of remote identity verification is a CONTROL matter under CDD_KYC and is excluded here.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-DEL-02", "prompt": "Business is materially placed or serviced through agents, intermediaries, introducers or other third parties.", "guidance": "Report count of active third parties and the share of relationships or value they originate or service. Whether they are supervised by the entity is assessed under THIRD_PARTY_OVERSIGHT.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$BUSINESS_MODEL_RISK$lit$, $json$[{"question_code": "IR-BUS-01", "prompt": "The ownership or group structure is complex, multi-jurisdictional or otherwise difficult to trace.", "guidance": "Consider layers between the entity and its ultimate beneficial owners, offshore holding vehicles, nominee arrangements and cross-border group entities relevant to AML operations.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "IR-BUS-02", "prompt": "Material growth or material change in the assessment period expanded or materially altered the entity's ML/TF exposure surface.", "guidance": "Measure the change in exposure surface: growth in customer numbers and value, entry into new products, services, channels or jurisdictions, and material structural change such as acquisition, disposal, new licence class, change of ownership or group reorganisation. The growth threshold is a configuration parameter ([MAT_GROWTH_RATE]). Record the figures and the change events relied on. Whether governance, staffing, systems, risk assessment, transaction monitoring, CDD or other controls kept pace with the change is assessed in the relevant CONTROL dimensions and must not influence the answer here.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$GOVERNANCE$lit$, $json$[{"question_code": "CT-GOV-01", "prompt": "The board has approved an AML/CFT framework appropriate to the nature, size and complexity of the entity, with documented accountability for each element.", "guidance": "Test the framework document, its approval, and whether the accountability map reaches named roles (not individuals in the methodology) for risk assessment, CDD, monitoring, reporting, testing and remediation. A generic policy adopted without tailoring to the business is at best PARTIALLY.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-GOV-02", "prompt": "The board and senior management receive AML/CFT management information sufficient in content, quality and frequency to oversee the framework, and there is evidence of challenge.", "guidance": "Look for coverage of risk-assessment outcomes, CDD backlogs, alert and case ageing, STR volumes and timeliness, screening exceptions, training completion, audit findings and overdue remediation. Evidence of challenge means recorded questions, requests and decisions, not receipt of a pack.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-GOV-03", "prompt": "AML/CFT issues escalated to the board or senior management resulted in decisions that were implemented and followed through within the period.", "guidance": "Trace a sample of escalated issues to decision, action, resource allocation and completion. Repeated escalation of the same issue without resolution is at best PARTIALLY.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$ENTERPRISE_RISK_ASSESSMENT$lit$, $json$[{"question_code": "CT-ERA-01", "prompt": "A documented enterprise-wide ML/TF risk assessment is current and formally approved.", "guidance": "Currency means updated within the entity own defined cycle and after material change. Approval must be by the body with authority under the framework. A draft or unapproved update is at best PARTIALLY.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-ERA-02", "prompt": "The risk-assessment methodology addresses the relevant risk factors and the entity own business drivers, with a documented rating basis.", "guidance": "Expect coverage of customer, geographic, product, channel and transaction factors, treatment of inherent versus residual risk, data used, and a rating basis that can be re-performed. Unexplained ratings, or a template with no entity-specific analysis, indicate a design gap.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-ERA-03", "prompt": "Risk-assessment outputs demonstrably drive the intensity of due diligence, monitoring and resourcing.", "guidance": "Trace at least two specific higher-risk conclusions into a control consequence (review frequency, EDD trigger, monitoring scenario, resourcing or training). Also test whether new or materially changed products were risk-assessed before launch.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$MLRO_FUNCTION$lit$, $json$[{"question_code": "CT-MLRO-01", "prompt": "A named compliance officer / MLRO is appointed at sufficient seniority, is fit and proper for the role, and is free from duties that conflict with the AML/CFT mandate.", "guidance": "Test appointment record, reporting line, authority to escalate directly, and whether revenue-generating or operational duties compromise independence. Deputy arrangements and continuity cover are in scope.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-MLRO-02", "prompt": "The AML/CFT function has resources, skills, data access and systems adequate for the entity risk profile, evidenced by the work actually completed in the period.", "guidance": "Compare planned versus completed AML activity: periodic reviews due and done, alerts and cases handled, backlogs, unfilled vacancies, reliance on overtime or deferral. Chronic backlog is evidence of inadequate resourcing regardless of assertions.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$POLICIES_PROCEDURES$lit$, $json$[{"question_code": "CT-POL-01", "prompt": "AML/CFT policies are current, approved and consistent with the applicable legal and regulatory requirements of the jurisdiction.", "guidance": "Map policy content to [LOCAL_AML_LEGISLATION_REF] and any supervisory rules or guidance in force. Gaps, superseded references or obligations not addressed reduce the response. Do not test against any jurisdiction not configured.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-POL-02", "prompt": "Policies are translated into operable procedures that staff actually use, and material changes are communicated and implemented.", "guidance": "Compare procedures with observed practice in a sample of files or cases. Look for version control, communication of change, and whether the procedure describes the system and steps in use rather than an aspiration.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$CDD_KYC$lit$, $json$[{"question_code": "CT-CDD-01", "prompt": "Customer due diligence is completed and verified before the business relationship is established or the occasional transaction is executed, with defined and controlled exceptions.", "guidance": "Test a risk-weighted sample. Where deferred verification is permitted, test whether the legal conditions, time limits and restrictions on activity are enforced systemically rather than by discretion.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-CDD-02", "prompt": "Ongoing due diligence and periodic refresh are executed to the risk-based schedule, with overdue populations controlled.", "guidance": "Obtain the ageing of due reviews by risk band. A material overdue population, or refresh driven by capacity rather than risk, reduces the response. Confirm trigger-event review as well as calendar review.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-CDD-03", "prompt": "Sample testing shows customer files are complete, accurate and current, including purpose and intended nature of the relationship and source of funds where required.", "guidance": "Sample across risk bands, channels and vintages. Record sample size, defects found and defect types. Systemic identical defects indicate a design failure and should be recorded as such in the observation.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$BENEFICIAL_OWNERSHIP$lit$, $json$[{"question_code": "CT-BO-01", "prompt": "Beneficial ownership and control are identified and verified to the required threshold, including for layered, cross-border and trust structures.", "guidance": "Test whether verification goes beyond self-declaration where risk requires, whether control not evidenced by shareholding is considered, and whether the entity records the point at which it stopped and why.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-BO-02", "prompt": "Beneficial ownership information is kept current and is reverified on defined trigger events.", "guidance": "Confirm triggers are defined (ownership change, adverse information, periodic review, transaction inconsistency) and evidence that they operated in the period.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$EDD$lit$, $json$[{"question_code": "CT-EDD-01", "prompt": "Enhanced due diligence is applied to every relationship that the risk framework identifies as higher risk, with measures that are genuinely enhanced.", "guidance": "Reconcile the higher-risk population from the risk framework against the population that actually received EDD. Enhanced means additional verification, source of wealth or funds, adverse-media enquiry and increased monitoring, not merely an extra approval box.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-EDD-02", "prompt": "Higher-risk relationships receive documented senior-management approval at inception and enhanced ongoing monitoring thereafter.", "guidance": "Check that approval precedes the relationship or the escalation to higher risk, is given by an authorised role, and that enhanced monitoring is evidenced in the period rather than assumed.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$PEP_CONTROLS$lit$, $json$[{"question_code": "CT-PEP-01", "prompt": "Domestic and foreign PEPs, their family members and close associates are identified at onboarding and on an ongoing basis, including where the PEP is a beneficial owner.", "guidance": "Test screening scope, data source currency, name-matching tolerance, and rescreening on list or status change. Self-declaration alone is insufficient where risk is material.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-PEP-02", "prompt": "PEP relationships are subject to senior approval, source-of-wealth enquiry, enhanced monitoring and periodic review, evidenced in the period.", "guidance": "Trace identified PEPs to approval, source-of-wealth evidence, monitoring treatment and the most recent review. Also test de-classification decisions where the person ceased to be a PEP.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$SANCTIONS_CONTROLS$lit$, $json$[{"question_code": "CT-SANC-01", "prompt": "Sanctions screening covers customers, beneficial owners, related parties and, where relevant, counterparties and payment fields, against the lists applicable in the jurisdiction.", "guidance": "Confirm which populations and data fields are screened, at what points (onboarding, ongoing, transaction), and against which lists ([LOCAL_SANCTIONS_LIST_REF]). Unscreened populations are a coverage gap even if screening quality is otherwise good.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-SANC-02", "prompt": "Sanctions lists are updated and the customer base rescreened without undue delay after a list change.", "guidance": "Obtain list-update logs and measure the interval from publication to load and to completed rescreening. Manual-only update processes require evidence of timeliness.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-SANC-03", "prompt": "Potential matches are investigated, escalated and resolved within defined timeframes, and the entity can give effect to a freezing or blocking obligation.", "guidance": "Sample match cases for timeliness, documented rationale for discounting, and escalation to the required authority. Test the operational ability to block or freeze, including where a third party executes the transaction.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$TRANSACTION_MONITORING$lit$, $json$[{"question_code": "CT-TM-01", "prompt": "The monitoring framework is designed to cover the entity products, customers, channels and geographies, with scenarios or rules traceable to identified risks.", "guidance": "Map monitoring scenarios or rules to the risks in the enterprise risk assessment and identify uncovered risks. Manual monitoring is acceptable where proportionate, but must be defined, allocated and evidenced.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-TM-02", "prompt": "Monitoring operates over complete and timely data for all in-scope products, channels and entities.", "guidance": "Reconcile transaction populations in source systems to what monitoring actually consumed, including agent, group and third-party channels. Exclusions must be documented, risk-assessed and approved.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-TM-03", "prompt": "Alert volumes, ageing and disposition are within approved thresholds, with no material backlog.", "guidance": "Obtain ageing by scenario and severity. Compare unclosed alerts to capacity. A backlog contradicts an assertion of effectiveness and must be recorded as a data contradiction where the entity asserts otherwise.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$ALERT_INVESTIGATION$lit$, $json$[{"question_code": "CT-ALRT-01", "prompt": "Alerts and cases are investigated within defined timeframes with a documented, reasoned disposition supported by the information reviewed.", "guidance": "Sample closed alerts across scenarios and analysts. Reject template rationales that do not address the triggering behaviour. Record timeliness against the entity own standard.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-ALRT-02", "prompt": "Investigation quality is subject to independent quality assurance, and identified defects are corrected.", "guidance": "QA must be performed by someone other than the investigator, cover a risk-based sample, and produce corrective action. QA that only counts timeliness is at best PARTIALLY.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$STR_IDENTIFICATION$lit$, $json$[{"question_code": "CT-STRI-01", "prompt": "Staff in customer-facing and processing roles are able to recognise indicators of suspicion relevant to the entity business and know the internal reporting channel.", "guidance": "Test through discussion, scenario questioning and the internal report record, not solely through training completion figures. Sector-relevant typologies should be reflected in the indicators used.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-STRI-02", "prompt": "Every internally reported suspicion creates a recorded, investigable case, and defined escalation triggers exist for identifying suspicion from monitoring, screening and external information.", "guidance": "Reconcile internal reports to cases created, and cases to decisions. Confirm triggers from alerts, adverse media, law-enforcement enquiries and customer behaviour are defined.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-STRI-03", "prompt": "Internal escalation of suspicion occurs promptly and cannot be suppressed by line management or commercial considerations.", "guidance": "Measure the interval from detection to receipt by the MLRO function. Test whether any intermediate approval can terminate a report, and whether staff can report directly. Filing itself is assessed under STR_GOVERNANCE.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$STR_GOVERNANCE$lit$, $json$[{"question_code": "CT-STRG-01", "prompt": "Authority to decide whether to file a suspicious transaction report is defined and exercised only by the authorised role, with the decision and its basis recorded for filed and not-filed cases alike.", "guidance": "Confirm the role, delegation and continuity arrangements. Not-filed decisions require the same rigour of record as filed ones.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-STRG-02", "prompt": "Reports are filed with the financial intelligence unit within the applicable deadline, evidenced by timeliness statistics for the period.", "guidance": "Measure decision-to-filing and detection-to-filing intervals against [LOCAL_STR_DEADLINE_REF]. Late filings require explanation and corrective action.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-STRG-03", "prompt": "Filed reports are complete and of sufficient quality, subject to quality assurance, and feedback from the FIU or supervisor is acted upon.", "guidance": "Review a sample of filings for narrative quality, inclusion of relevant parties and transactions, and attachments. Check whether feedback received led to change.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-STRG-04", "prompt": "Confidentiality and tipping-off controls operate, records of suspicion are securely retained, and there is no material backlog of undecided cases.", "guidance": "Test access restriction to STR records, staff understanding of the prohibition on disclosure, retention against [LOCAL_RETENTION_REF], and the ageing of undecided suspicions.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$RECORD_KEEPING$lit$, $json$[{"question_code": "CT-RK-01", "prompt": "Records of due diligence, transactions, internal and external suspicion reports and training are retained for the required period in a usable form.", "guidance": "Confirm the retention schedule covers each record class, applies to records held by third parties, and matches [LOCAL_RETENTION_REF]. Verify safeguards against premature deletion.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-RK-02", "prompt": "Records can be retrieved completely and promptly on supervisory or competent-authority request, demonstrated in the period.", "guidance": "Use actual request history or a live retrieval test. Include archived, migrated and third-party-held records.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$TRAINING$lit$, $json$[{"question_code": "CT-TRN-01", "prompt": "A role-based AML/CFT training programme exists, covering the board, senior management, customer-facing staff, operations and the AML function, at a defined frequency.", "guidance": "Uniform generic training for all roles is at best PARTIALLY where the business has materially different role exposures. Confirm board and senior-management coverage explicitly.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-TRN-02", "prompt": "Training was delivered as planned in the period, new joiners were trained before or on commencement of relevant duties, and the overdue population is immaterial.", "guidance": "Obtain completion and overdue reports by role and business unit. Identify staff performing AML-relevant duties without current training. Quantify rather than accept an assertion.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-TRN-03", "prompt": "Training effectiveness is tested, and failures or knowledge gaps lead to remedial action.", "guidance": "Look for assessment results, pass thresholds, retesting, and targeted remediation where staff performance or incidents indicate gaps.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$INDEPENDENT_TESTING$lit$, $json$[{"question_code": "CT-IT-01", "prompt": "AML/CFT independent testing is performed by a function or party independent of AML operations, with a mandate and unrestricted scope.", "guidance": "Independence means not designing or operating the controls tested. Internal audit, group audit or a qualified external party are all acceptable. Self-assessment by the AML function is not independent testing.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-IT-02", "prompt": "The testing scope, frequency and depth are risk-based and include substantive sample testing rather than policy review alone.", "guidance": "Review the plan and completed work for coverage of higher-risk areas, sample sizes, re-performance, and periods since each area was last tested. Consecutive years with no coverage of a high-risk control is a gap.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-IT-03", "prompt": "Independent-testing results are reported to the board or audit committee, with severity and management response recorded.", "guidance": "Look for the reporting pack, minutes and the management response. Do not re-test closure evidence here — that is CT-REM-03.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$THIRD_PARTY_OVERSIGHT$lit$, $json$[{"question_code": "CT-TPO-01", "prompt": "AML/CFT due diligence is performed on agents, intermediaries, introducers and outsourced providers before appointment.", "guidance": "Expect assessment of ownership and control, licensing, AML capability, adverse information and jurisdiction. Reliance on group membership alone is insufficient where the provider performs AML-relevant work.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-TPO-02", "prompt": "Contracts impose AML/CFT obligations, data and record access, audit rights, breach notification and termination rights.", "guidance": "Sample agreements for these clauses and for the entity right to obtain underlying CDD records without delay. Ultimate responsibility remaining with the entity must be reflected.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-TPO-03", "prompt": "Third parties are monitored on a risk-based basis during the relationship, and identified breaches lead to escalation, remediation or termination.", "guidance": "Look for risk-rated review cycles, file or transaction sampling of third-party originated business, performance and exception MI, and evidence of action taken where standards were not met.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$AML_DATA_QUALITY$lit$, $json$[{"question_code": "CT-DQ-01", "prompt": "Critical AML data elements are defined, and the data held in source systems is materially complete and accurate for those elements.", "guidance": "Critical AML data elements should be defined and their completeness, accuracy and timeliness measured, including the feeds into screening and monitoring. Defect-rate thresholds are configuration parameters ([MAT_CDE_DEFECT_RATE]). Absorbs the reconciliation scope of the retired CT-DQ-02.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-DQ-03", "prompt": "Data-quality defects affecting AML controls are recorded with an owner and due date and are remediated.", "guidance": "Confirm defects are logged, prioritised by AML impact, and remediated; check for long-standing accepted defects with no compensating control.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$MODEL_GOVERNANCE$lit$, $json$[{"question_code": "CT-MG-01", "prompt": "Monitoring and screening rules, scenarios, thresholds and models are inventoried, with a named owner and documented purpose for each.", "guidance": "Applies equally to spreadsheet or manual rule sets. Undocumented or orphaned rules, and rules disabled without approval, reduce the response.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-MG-02", "prompt": "Detection logic is independently reviewed or validated before deployment and periodically thereafter, proportionate to its complexity and reliance.", "guidance": "For statistical models expect validation; for rule or scenario systems expect documented independent review of logic, coverage and data. Vendor certification alone is not entity-specific validation.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-MG-03", "prompt": "Changes to rules, scenarios and thresholds follow change control, are supported by tuning analysis, and performance is monitored with limitations documented.", "guidance": "Expect approval of changes by an authorised role, above and below-the-line testing for threshold changes, false-positive and productivity monitoring, and a record of known limitations and compensating measures.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);
INSERT INTO tmp_dim_questions VALUES ($lit$REMEDIATION_TRACKING$lit$, $json$[{"question_code": "CT-REM-01", "prompt": "AML/CFT issues from all sources are captured in a single register with severity, named owner, agreed action and due date.", "guidance": "Sources include self-identified issues, QA and data-quality defects, independent testing, external audit, supervisory findings and enforcement conditions. A register missing a source is incomplete.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": false, "na_requires_rationale": true}, {"question_code": "CT-REM-02", "prompt": "Progress is tracked, and overdue or at-risk actions are escalated to the accountable governance forum.", "guidance": "Obtain overdue and extension statistics. Repeated extension without escalation, or re-dating of due dates, reduces the response and should be recorded with figures.", "mandatory": true, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}, {"question_code": "CT-REM-03", "prompt": "Closure is supported by validation evidence, and repeat or recurring findings are analysed for root cause.", "guidance": "Confirm an independent or second-line check before closure and look for the same issue recurring across periods, which indicates root cause was not addressed.", "mandatory": false, "requires_observation": true, "requires_evidence": true, "min_evidence_count": 1, "allow_not_applicable": true, "na_requires_rationale": true}]$json$::jsonb);

CREATE TEMP TABLE tmp_payload(kind text PRIMARY KEY, payload jsonb) ON COMMIT DROP;
