other questions)", "evidence_basis_types": ["STRUCTURED_METRIC", "SYSTEM_FACT", "REGULATORY_RETURN", "ENTERPRISE_DOCUMENT", "AUTHORISED_EXTERNAL_SOURCE", "RFI_RESPONSE"], "supervisory_judgement_required": true, "factual_auto_prefill_possible": true, "standards_reference": "FATF R.10, R.19", "standards_reference_strength": "RELATED_RISK_FACTOR", "standards_reference_review": "Mapping accepted as stated", "sector_classification": "CORE", "sector_notes": "Ordinarily low for domestic credit unions; material for international banking, MSBs and VASPs.", "sector_applicability": "CORE_WITH_SECTOR_GUIDANCE", "change_classification": "NEW", "predecessor_mapping": "None (new in v1.1)", "fact_codes": ["FACT-NONRES-SHARE", "FACT-NONRES-VALUE-SHARE"], "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "MIPL_REFERENCE", "reference_decisions": ["AML-METH-01", "AML-METH-04", "AML-METH-06", "AML-METH-07"], "candidate_data_sources": "entity profile, regulatory returns, ownership/person relationships, examination history", "suggested_evidence_types": "Enterprise ML/TF risk assessment, customer risk-classification report / segmentation extract, regulatory return customer schedules"}}, {"question_code": "IR-CUS-04", "axis": "INHERENT_EXPOSURE", "effectiveness_focus": "INHERENT_EXPOSURE", "question_class": "CORE", "response_semantics_code": "INHERENT_SEM", "calculation_participation": "SCORED", "trigger_condition": "Not applicable — CORE question", "supervisory_intent": "Measure PEP exposure as a risk characteristic, independent of the quality of PEP controls.", "na_conditions": "The entity demonstrably serves no natural-person or beneficially-owned relationships in scope for PEP determination.", "minimum_evidence_note": "1 governed evidence basis (may be shared with other questions)", "evidence_basis_types": ["STRUCTURED_METRIC", "SYSTEM_FACT", "REGULATORY_RETURN", "ENTERPRISE_DOCUMENT", "AUTHORISED_EXTERNAL_SOURCE", "RFI_RESPONSE"], "supervisory_judgement_required": true, "factual_auto_prefill_possible": true, "standards_reference": "FATF R.12", "standards_reference_strength": "RELATED_RISK_FACTOR", "standards_reference_review": "Mapping accepted as stated", "sector_classification": "CORE", "sector_notes": "Judge relative to entity size, not absolute count.", "sector_applicability": "CORE_ALL", "change_classification": "NEW", "predecessor_mapping": "None (new in v1.1)", "fact_codes": ["FACT-PEP-COUNT", "FACT-PEP-SHARE"], "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "MIPL_REFERENCE", "reference_decisions": ["AML-METH-01", "AML-METH-04", "AML-METH-06", "AML-METH-07"], "candidate_data_sources": "entity profile, regulatory returns, ownership/person relationships, examination history", "suggested_evidence_types": "Enterprise ML/TF risk assessment, customer risk-classification report / segmentation extract, regulatory return customer schedules"}}, {"question_code": "IR-GEO-01", "axis": "INHERENT_EXPOSURE", "effectiveness_focus": "INHERENT_EXPOSURE", "question_class": "CORE", "response_semantics_code": "INHERENT_SEM", "calculation_participation": "SCORED", "trigger_condition": "Not applicable — CORE question", "supervisory_intent": "Measure jurisdictional exposure arising from customers, counterparties, beneficial owners and flows.", "na_conditions": "Not permitted", "minimum_evidence_note": "1 governed evidence basis (may be shared with other questions)", "evidence_basis_types": ["STRUCTURED_METRIC", "SYSTEM_FACT", "REGULATORY_RETURN", "ENTERPRISE_DOCUMENT", "AUTHORISED_EXTERNAL_SOURCE", "RFI_RESPONSE"], "supervisory_judgement_required": true, "factual_auto_prefill_possible": true, "standards_reference": "FATF R.19, INR.10", "standards_reference_strength": "RELATED_RISK_FACTOR", "standards_reference_review": "Mapping accepted as stated", "sector_classification": "CORE", "sector_notes": "Sector-neutral; measurement source differs (returns vs payment data).", "sector_applicability": "CORE_ALL", "change_classification": "SEMANTIC_CORRECTION", "predecessor_mapping": "GEOGRAPHIC_RISK.Q1", "fact_codes": ["FACT-HRJ-EXPOSURE-VALUE", "FACT-HRJ-EXPOSURE-SHARE"], "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "MIPL_REFERENCE", "reference_decisions": ["AML-METH-01", "AML-METH-04", "AML-METH-06", "AML-METH-07"], "candidate_data_sources": "regulatory returns, entity profile, external intelligence where authorised", "suggested_evidence_types": "Country exposure report, cross-border flow analysis, correspondent relationship register"}}, {"question_code": "IR-GEO-02", "axis": "INHERENT_EXPOSURE", "effectiveness_focus": "INHERENT_EXPOSURE", "question_class": "CONDITIONAL", "response_semantics_code": "INHERENT_SEM", "calculation_participation": "SCORED", "trigger_condition": "Entity undertakes cross-border, correspondent, remittance or payment-corridor business.", "supervisory_intent": "Measure cross-border exposure once, using corridor, correspondent and flow facts.", "na_conditions": "The entity conducts no cross-border activity of any kind in the assessment period.", "minimum_evidence_note": "1 governed evidence basis (may be shared with other questions)", "evidence_basis_types": ["STRUCTURED_METRIC", "SYSTEM_FACT", "REGULATORY_RETURN", "ENTERPRISE_DOCUMENT", "AUTHORISED_EXTERNAL_SOURCE", "RFI_RESPONSE"], "supervisory_judgement_required": true, "factual_auto_prefill_possible": true, "standards_reference": "FATF R.13, R.14, R.16", "standards_reference_strength": "RELATED_RISK_FACTOR", "standards_reference_review": "Mapping accepted as stated", "sector_classification": "SECTOR_SENSITIVE", "sector_notes": "Central for banks, MSBs and VASPs; often not applicable for domestic-only insurers.", "sector_applicability": "SECTOR_OVERLAY_CANDIDATE", "change_classification": "SPLIT", "predecessor_mapping": "GEOGRAPHIC_RISK.Q2", "fact_codes": ["FACT-XBORDER-VOLUME", "FACT-XBORDER-VALUE", "FACT-CORRESPONDENT-COUNT"], "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "MIPL_REFERENCE", "reference_decisions": ["AML-METH-01", "AML-METH-04", "AML-METH-06", "AML-METH-07"], "candidate_data_sources": "regulatory returns, entity profile, external intelligence where authorised", "suggested_evidence_types": "Country exposure report, cross-border flow analysis, correspondent relationship register"}}, {"question_code": "IR-GEO-03", "axis": "INHERENT_EXPOSURE", "effectiveness_focus": "INHERENT_EXPOSURE", "question_class": "CONDITIONAL", "response_semantics_code": "CONTEXT_FACT_SEM", "calculation_participation": "CONTEXTUAL_NOT_SCORED", "trigger_condition": "Contextual fact — asked where cross-border or corridor activity exists; never scored.", "supervisory_intent": "Record the concentration profile so the supervisor can interpret IR-GEO-01 and IR-GEO-02; concentration is not itself higher or lower ML/TF exposure.", "na_conditions": "The entity conducts no cross-border activity of any kind in the assessment period.", "minimum_evidence_note": "1 governed evidence basis (may be shared with other questions)", "evidence_basis_types": ["STRUCTURED_METRIC", "SYSTEM_FACT", "REGULATORY_RETURN", "ENTERPRISE_DOCUMENT", "AUTHORISED_EXTERNAL_SOURCE", "RFI_RESPONSE"], "supervisory_judgement_required": true, "factual_auto_prefill_possible": true, "standards_reference": "FATF R.1", "standards_reference_strength": "SUPERVISORY_GUIDANCE_CONTEXT", "standards_reference_review": "No FATF provision addresses corridor concentration — reference reduced to supervisory context and the question made contextual/non-scoring.", "sector_classification": "CORE", "sector_notes": null, "sector_applicability": "SECTOR_CONDITIONAL", "change_classification": "NEW", "predecessor_mapping": "None (new in v1.1)", "fact_codes": ["FACT-CORRIDOR-TOP1-SHARE", "FACT-CORRIDOR-TOP3-SHARE", "FACT-CORRIDOR-RISK-CLASS"], "provenance": {"source_document"