", "unit": "%", "numerator_basis": "REQUIRED_NOT_YET_DEFINED", "denominator_basis": "REQUIRED_NOT_YET_DEFINED", "period_expectation": "ASSESSMENT_PERIOD", "materiality_parameter_code": "MAT_GROWTH_RATE", "is_required": false, "auto_prefill_allowed": false, "officer_edit_allowed": true, "attribute_source": "DERIVED_FROM_FACT_CODE_CONVENTION", "definition_status": "ATTRIBUTES_PENDING", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-evidence-data-source-map.md", "decision_layer": "MIPL_REFERENCE"}}, {"fact_code": "FACT-VELOCITY-INDEX", "label": "Velocity Index", "data_type": "decimal", "unit": "index", "numerator_basis": null, "denominator_basis": null, "period_expectation": "ASSESSMENT_PERIOD", "materiality_parameter_code": null, "is_required": false, "auto_prefill_allowed": false, "officer_edit_allowed": true, "attribute_source": "DERIVED_FROM_FACT_CODE_CONVENTION", "definition_status": "ATTRIBUTES_PENDING", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-evidence-data-source-map.md", "decision_layer": "MIPL_REFERENCE"}}, {"fact_code": "FACT-XBORDER-VALUE", "label": "Xborder Value", "data_type": "currency", "unit": "currency", "numerator_basis": null, "denominator_basis": null, "period_expectation": "ASSESSMENT_PERIOD", "materiality_parameter_code": null, "is_required": false, "auto_prefill_allowed": false, "officer_edit_allowed": true, "attribute_source": "DERIVED_FROM_FACT_CODE_CONVENTION", "definition_status": "ATTRIBUTES_PENDING", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-evidence-data-source-map.md", "decision_layer": "MIPL_REFERENCE"}}, {"fact_code": "FACT-XBORDER-VOLUME", "label": "Xborder Volume", "data_type": "integer", "unit": "count", "numerator_basis": null, "denominator_basis": null, "period_expectation": "ASSESSMENT_PERIOD", "materiality_parameter_code": null, "is_required": false, "auto_prefill_allowed": false, "officer_edit_allowed": true, "attribute_source": "DERIVED_FROM_FACT_CODE_CONVENTION", "definition_status": "ATTRIBUTES_PENDING", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-evidence-data-source-map.md", "decision_layer": "MIPL_REFERENCE"}}]$json$::jsonb);
INSERT INTO tmp_payload VALUES ('parameters', $json$[{"parameter_code": "MAT_HIGH_RISK_CUSTOMER_SHARE", "parameter_kind": "MATERIALITY", "label": "Higher-risk customer share materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_HIGH_RISK_VALUE_SHARE", "parameter_kind": "MATERIALITY", "label": "Higher-risk customer value share materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_CASH_VALUE_SHARE", "parameter_kind": "MATERIALITY", "label": "Cash transaction value share materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_XBORDER_VALUE_SHARE", "parameter_kind": "MATERIALITY", "label": "Cross-border value share materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_CORRIDOR_TOP1_SHARE", "parameter_kind": "MATERIALITY", "label": "Largest corridor concentration materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_CORRIDOR_TOP3_SHARE", "parameter_kind": "MATERIALITY", "label": "Top three corridor concentration materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_GROWTH_RATE", "parameter_kind": "MATERIALITY", "label": "Customer or value growth-rate materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}, {"parameter_code": "MAT_CDE_DEFECT_RATE", "parameter_kind": "MATERIALITY", "label": "Critical data element defect-rate materiality", "data_type": "percentage", "unit": "%", "provenance": {"source_document": "docs/aml/AML-CFT-RBA-v1.1-question-catalogue.md", "decision_layer": "AWAITING_REGULATOR_CALIBRATION"}}]$json$::jsonb);
INSERT INTO tmp_payload VALUES ('semantics', $json$[{"semantic_code": "INHERENT_SEM", "label": "Inherent exposure", "description": "Response meaning for inherent ML/TF exposure questions.", "response_meaning": {"YES": "The exposure characteristic is present and material to the entity, judged against the materiality criteria in the guidance.", "PARTIALLY": "The exposure characteristic exists but is limited, bounded or below the materiality criteria.", "NO": "The exposure characteristic is absent or immaterial for the assessment period.", "NOT_APPLICABLE": "The underlying activity is genuinely not undertaken in the assessment period (not: unknown, unevidenced or unanswered)."}}, {"semantic_code": "CONTROL_SEM_DESIGN", "label": "Control effectiveness — design", "description": "Design-only control question; operating evidence is not required.", "response_meaning": {"YES": "The control is appropriately designed and proportionate to this entity's risk, nature, size and complexity.", "PARTIALLY": "Material design gaps leave residual weakness.", "NO": "The control is absent, or so weak in design that it cannot be relied upon.", "NOT_APPLICABLE": "The activity the control addresses is genuinely not undertaken, so the control cannot exist."}}, {"semantic_code": "CONTROL_SEM_OPERATING", "label": "Control effectiveness — operating", "description": "Operating-effectiveness control question; period, sample or system evidence is required.", "response_meaning": {"YES": "The control operated effectively over the relevant period or sample, evidenced by period data, samples or system facts.", "PARTIALLY": "Evidenced exceptions in operation leave residual weakness.", "NO": "The control is absent, or so weak in operation that it cannot be relied upon.", "NOT_APPLICABLE": "The activity the control addresses is genuinely not undertaken, so the control cannot exist."}}, {"semantic_code": "CONTROL_SEM_DESIGN_AND_OPERATING", "label": "Control effectiveness — design and operating", "description": "Both design adequacy and operating effectiveness must hold for a favourable response.", "response_meaning": {"YES": "The control is appropriately designed and operated effectively over the relevant period or sample.", "PARTIALLY": "Material design gaps or evidenced operating exceptions leave residual weakness.", "NO": "The control is absent, or so weak in design or operation that it cannot be relied upon.", "NOT_APPLICABLE": "The activity the control addresses is genuinely not undertaken, so the control cannot exist."}}, {"semantic_code": "CONTEXT_FACT_SEM", "label": "Contextual fact", "description": "A contextual fact is recorded; no favourable or adverse polarity, never scored.", "response_meaning": {"RECORDED": "The contextual fact has been recorded with its provenance.", "NOT_AVAILABLE": "The contextual fact could not be obtained; the reason is recorded."}}]$json$::jsonb);
INSERT INTO tmp_payload VALUES ('decisions', $json$[{"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-01", "title": "Adopt the exposure -> control -> residual -> judgement -> response chain, with question classes", "decision_text": "Adopt the chain, and adopt the CORE / CONDITIONAL / ENHANCED question-class model so that a catalogue question is not automatically mandatory in every assessment.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-02", "title": "Inherent question set: 17 inherent questions across 6 dimensions — 12 CORE / 5 CONDITIONAL — 16 scored / 1 contextual non-scored", "decision_text": "Adopt the red-teamed set. `IR-BUS-03` (outsourced/intragroup AML operations) is moved to control effectiveness (`THIRD_PARTY_OVERSIGHT`); `IR-TRX-02` merges into `IR-PRD-02` (cash) and `IR-TRX-03` into `IR-GEO-02` (cross-border); `IR-DEL-03` merges into `IR-DEL-01`/`IR-PRD-03`; `IR-GEO-03` (corridor concentration) is recorded as a contextual, non-scored fact because concentration in lower-risk corridors is not higher inherent exposure. Every remaining scored inherent question satisfies: `YES` = more inherent ML/TF exposure before controls.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-03", "title": "Control question set: 53 questions across 20 dimensions (36 CORE, 11 CONDITIONAL, 6 ENHANCED)", "decision_text": "Adopt with the closure changes: `CT-DQ-02` retired (reconciliation absorbed by `CT-DQ-01` and `CT-TM-02`); `CT-IT-03` narrowed to board reporting so closure validation is assessed once, in `CT-REM-03`; file/alert/report sampling and training-effectiveness testing (`CT-CDD-03`, `CT-ALRT-02`, `CT-STRI-03`, `CT-STRG-03`, `CT-TRN-03`, `CT-REM-03`) classified ENHANCED (examination/thematic); third-party oversight and model governance classified CONDITIONAL on the presence of third parties or automated detection.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-04", "title": "Context-sensitive response semantics per axis and effectiveness focus", "decision_text": "Adopt `INHERENT_SEM`, `CONTROL_SEM_DESIGN`, `CONTROL_SEM_OPERATING`, `CONTROL_SEM_DESIGN_AND_OPERATING` and `CONTEXT_FACT_SEM`. A pure DESIGN question must not require operating evidence merely because a global control definition demanded it.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-05", "title": "Selective design vs operating-effectiveness split (14 DESIGN / 27 OPERATING / 12 DESIGN_AND_OPERATING)", "decision_text": "Adopt as catalogued; split only where the operating failure mode is distinct.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-06", "title": "Evidence basis (replaces the \"observation + one evidence item per question\" mandate)", "decision_text": "Every **final supervisory response** must carry (A) a rationale/observation appropriate to the judgement and (B) a sufficient **governed evidence basis**. An evidence basis may be an `ENTERPRISE_DOCUMENT`, `SYSTEM_FACT`, `REGULATORY_RETURN`, `STRUCTURED_METRIC`, `SUPERVISORY_SAMPLE`, `WORKPAPER`, `PRIOR_EXAMINATION`, `FINDING`, `REMEDIATION_RECORD`, `RFI_RESPONSE` or `AUTHORISED_EXTERNAL_SOURCE`. One document or governed fact may support several questions; a question need not create a duplicate evidence object. For purely system-factual questions, structured provenance (source, period, timestamp, extraction reference) satisfies the evidence requirement. No assertion-only favourable conclusion. No AML-local document store; references are governed references into existing platform records.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-07", "title": "N/A discipline: enumerated conditions only, rationale always required; N/A distinguished from NOT_TRIGGERED and NOT_ASKED", "decision_text": "Adopt. `NOT_APPLICABLE` (activity genuinely not undertaken), `NOT_TRIGGERED` (conditional trigger absent) and `NOT_ASKED` / `OUT_OF_SCOPE` (enhanced question outside this assessment's scope) are three distinct states; none may silently score zero or full, and none is a favourable response.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-08", "title": "Legacy `STR_SAR_GOVERNANCE`: governed audited relink to `STR_GOVERNANCE` (supersedes the display-only recommendation)", "decision_text": "If the methodology owner confirms that `STR_SAR_GOVERNANCE` is the semantic predecessor of `STR_GOVERNANCE`, execute a **governed, audited, idempotent relink** of the 22 rows to canonical `STR_GOVERNANCE`, preserving the original dimension code and provenance, assessment status, responses, judged ratings and history. Because the rows hold no responses and no calculated results, no rating is invented. Display/lineage-only mapping is rejected as a final route: it leaves LINK-11 permanently open and is therefore not an acceptable certification path.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-09", "title": "Global AML/CFT core plus sector applicability/overlay capability (supersedes the single-catalogue-with-N/A approach)", "decision_text": "Adopt a **global core** (44 CORE_ALL, 4 CORE_WITH_SECTOR_GUIDANCE) with **13 SECTOR_CONDITIONAL** questions resolved by trigger and **9 SECTOR_OVERLAY_CANDIDATE** questions (correspondent/remittance corridors, virtual-asset and complex products, agent networks, automated detection and model governance) earmarked for sector overlays. Overlays should later be expressed as sector-scoped applicability and guidance records over the same canonical question catalogue, resolved through the existing entity-context methodology resolver — duplicating no question text, evidence contract, document or storage architecture. Sectors analysed: banks, credit unions, insurance, securities, MSBs, VASPs, DNFBPs, other.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}, {"domain_code": "AML_CFT", "methodology_code": "AML-CFT-RBA", "methodology_version": "1.1", "decision_code": "AML-METH-10", "title": "v1.0 -> v1.1 transition, by assessment status", "decision_text": "APPROVED / SUPERSEDED v1.0 assessments are never re-versioned and remain reproducible. DRAFT v1.0 assessments may be abandoned or superseded and recreated under v1.1 through a governed, audited process where the supervisor decides that is appropriate. SUBMITTED / REVIEWED v1.0 assessments require an explicit supervisory decision per assessment: finish under v1.0, or return/cancel and restart under v1.1. Never silently re-version. No migration in this wave.", "rationale": "Reference design approved by the platform methodology owner (MIPL) for the AML-CFT-RBA v1.1 reference catalogue. Reference approval only: it does not constitute approval by any regulator and does not authorise use in a live supervisory decision until the regulator adopts it.", "provenance": {"source_document": "docs/aml/AML-CFT-methodology-calculation-decision-pack.md", "decision_layer": "MIPL_REFERENCE"}}]$json$::jsonb);

DO $apply$
DECLARE
  v_actor   uuid;
  v_active  uuid;
  v_draft   uuid;
  v_dim     record;
  v_dim_id  uuid;
  v_n       integer;
  v_total   integer := 0;
BEGIN
  SELECT id INTO v_actor FROM auth.users
   WHERE email = 'super_admin@mishainfotech.com';
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'no methodology administrator identity available';
  END IF;
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', v_actor::text, 'role', 'authenticated')::text, true);

  SELECT id INTO v_active FROM public.supervisory_methodology
   WHERE code = 'AML-CFT-RBA' AND domain_code = 'AML_CFT' AND status = 'ACTIVE'
   ORDER BY version DESC LIMIT 1;
  IF v_active IS NULL THEN
    RAISE EXCEPTION 'refused: no ACTIVE AML-CFT-RBA version to supersede';
  END IF;

  SELECT id INTO v_draft FROM public.supervisory_methodology
   WHERE code = 'AML-CFT-RBA' AND domain_code = 'AML_CFT' AND version = '1.1';
  IF v_draft IS NULL THEN
    v_draft := public.supervisory_methodology_new_version(
      v_active, '1.1',
      'Create AML-CFT-RBA v1.1 DRAFT to carry the MIPL reference question catalogue; v1.0 remains ACTIVE and structurally frozen.');
    RAISE NOTICE 'created v1.1 DRAFT %', v_draft;
  ELSE
    RAISE NOTICE 'reusing existing v1.1 draft %', v_draft;
  END IF;

  IF (SELECT status FROM public.supervisory_methodology WHERE id = v_draft) <> 'DRAFT' THEN
    RAISE EXCEPTION 'refused: v1.1 is no longer DRAFT; author a further version instead';
  END IF;

  -- Replace the inherited v1.0 question set (no responses exist on a draft version).
  PERFORM public.supervisory_methodology_question_purge(
    v_draft,
    'Replace the inherited v1.0 question set with the approved AML-CFT-RBA v1.1 reference catalogue.');

  -- Reference vocabularies and the quantitative fact contract.
  PERFORM public.supervisory_methodology_semantic_profile_set(
    'AML_CFT', (SELECT payload FROM tmp_payload WHERE kind = 'semantics'));
  PERFORM public.supervisory_methodology_parameter_set(
    v_draft, (SELECT payload FROM tmp_payload WHERE kind = 'parameters'));
  PERFORM public.supervisory_methodology_fact_requirement_set(
    v_draft, (SELECT payload FROM tmp_payload WHERE kind = 'facts'));

  -- Questions, dimension by dimension, through the canonical dimension save.
  FOR v_dim IN
    SELECT t.dimension_code, t.questions, d.*
      FROM tmp_dim_questions t
      JOIN public.supervisory_methodology_dimension d
        ON d.methodology_id = v_draft AND d.dimension_code = t.dimension_code
  LOOP
    v_dim_id := public.supervisory_methodology_dimension_save(v_draft, jsonb_build_object(
      'dimension_code', v_dim.dimension_code,
      'dimension_group', v_dim.dimension_group,
      'dimension_kind', v_dim.dimension_kind,
      'label', v_dim.label,
      'description', v_dim.description,
      'weight', v_dim.weight,
      'evidence_required', v_dim.evidence_required,
      'sort_order', v_dim.sort_order,
      'active', v_dim.active,
      'scoring_guidance', v_dim.scoring_guidance,
      'data_sources', v_dim.data_sources,
      'evidence_requirements', v_dim.evidence_requirements,
      'min_evidence_count', 1,
      'mandatory_questions', v_dim.questions));
    v_total := v_total + jsonb_array_length(v_dim.questions);
  END LOOP;

  IF (SELECT count(*) FROM tmp_dim_questions t
       WHERE NOT EXISTS (SELECT 1 FROM public.supervisory_methodology_dimension d
                          WHERE d.methodology_id = v_draft
                            AND d.dimension_code = t.dimension_code)) > 0 THEN
    RAISE EXCEPTION 'refused: the catalogue references a dimension that does not exist in v1.1';
  END IF;

  v_n := public.supervisory_methodology_question_attributes_set(
    v_draft, (SELECT payload FROM tmp_payload WHERE kind = 'attributes'));
  RAISE NOTICE 'questions written %, attributes applied %', v_total, v_n;

  PERFORM public.supervisory_methodology_reference_decision_record(
    (SELECT payload FROM tmp_payload WHERE kind = 'decisions'));

  IF (SELECT count(*) FROM public.supervisory_methodology_question
       WHERE methodology_id = v_draft AND active) <> 70 THEN
    RAISE EXCEPTION 'refused: v1.1 does not carry exactly 70 active questions';
  END IF;
END $apply$;

COMMIT;
